<?php
require __DIR__.'/../config/database.php';require __DIR__.'/../includes/functions.php';require_role(['staff','admin']);
$rows=$pdo->query('SELECT a.application_id,a.status,a.submitted_at,u.full_name,u.email,s.title,(SELECT COUNT(*) FROM application_documents d WHERE d.application_id=a.application_id) document_count FROM applications a JOIN users u ON u.user_id=a.student_id JOIN scholarships s ON s.scholarship_id=a.scholarship_id ORDER BY a.submitted_at DESC')->fetchAll();
$pageTitle='Review Applications';require __DIR__.'/../includes/header.php';?>
<section class="staff-intro"><p class="eyebrow">STAFF WORKSPACE</p><h1>Review applications</h1><p class="muted">Open an application to review the student's submitted profile snapshot, answers and supporting documents.</p></section>
<div class="table-wrap"><table><tr><th>Student</th><th>Scholarship</th><th>Submitted</th><th>Documents</th><th>Status</th><th>Review</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['submitted_at'])?></td><td><?=(int)$r['document_count']?></td><td><span class="status-pill"><?=e($r['status'])?></span></td><td><a class="button" href="application_review.php?id=<?=(int)$r['application_id']?>">Open review</a></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p>No applications have been submitted yet.</p><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
